        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;700&display=swap');
        @import url('https://fonts.googleapis.com/css2?family=Source+Serif+Pro:ital,wght@1,400&display=swap');

        :root {
            --bg-color: #FFF0F5; /* 柔和的樱花粉或淡薰衣草色背景 */
            --surface-color: rgba(255, 255, 255, 0.75); /* 半透明的白色表面 */
            --primary-text-color: #5D4361; /* 温柔的深紫色文字 */
            --secondary-text-color: #8C7891; /* 柔和的灰紫色次要文字 */
            --accent-color: #E6A4CB; /* 更明亮、饱和的粉紫色作为强调色 */
            --glow-color: rgba(230, 164, 203, 0.7); /* 漂浮物的辉光颜色 */
            --divider-color: rgba(93, 67, 97, 0.1); /* 浅紫色分割线 */
            --font-family: 'Noto Sans SC', sans-serif;
            --serif-font-family: 'Source Serif Pro', 'KaiTi', serif;
            --border-radius: 12px;
            --transition-speed: 0.5s;
        }

        body {
            background-color: var(--bg-color);
            color: var(--primary-text-color);
            font-family: var(--font-family);
            margin: 0;
            padding: 30px 20px;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            line-height: 1.7;
            position: relative;
            overflow: hidden;
        }

        /* 流光背景 - 增强版 */
        body::before {
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: linear-gradient(
                45deg,
                rgba(255, 255, 255, 0.5),
                rgba(230, 164, 203, 0.4) 25%,
                rgba(255, 255, 255, 0.5) 50%,
                rgba(230, 164, 203, 0.4) 75%,
                rgba(255, 255, 255, 0.5)
            );
            background-size: 200% 200%;
            animation: flowingShine 12s linear infinite; /* 速度加快，线性运动更平滑 */
            z-index: 1;
        }

        @keyframes flowingShine {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        /* 漂浮粒子 - 增强版 */
        .particles {
            position: absolute;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: 1;
            pointer-events: none; /* 确保粒子不影响交互 */
        }

        .particle {
            position: absolute;
            background-color: var(--accent-color);
            border-radius: 50%;
            opacity: 0;
            animation: floatUp 12s infinite ease-in;
            /* 增强辉光效果 */
            box-shadow: 0 0 12px 2px var(--glow-color), 0 0 20px 5px var(--glow-color);
        }

        @keyframes floatUp {
            0% {
                transform: translateY(100vh) scale(0.3);
                opacity: 0;
            }
            10%, 90% {
                opacity: 0.8;
            }
            100% {
                transform: translateY(-5vh) scale(1.2);
                opacity: 0;
            }
        }

        .profile-container {
            width: 100%;
            max-width: 650px;
            background-color: var(--surface-color);
            border-radius: var(--border-radius);
            box-shadow: 0 10px 40px rgba(93, 67, 97, 0.15);
            overflow: hidden;
            border: 1px solid var(--divider-color);
            position: relative;
            z-index: 2;
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
        }

        .profile-header {
            padding: 32px;
            text-align: center;
            border-bottom: 1px solid var(--divider-color);
        }

        .profile-header .verdict {
            font-family: var(--serif-font-family);
            font-size: 1.1rem;
            color: var(--primary-text-color);
            margin: 0;
            font-style: italic;
        }

        .accordion {
            padding: 10px 16px;
        }

        .accordion-item {
            border-bottom: 1px solid var(--divider-color);
        }
        .accordion-item:last-child {
            border-bottom: none;
        }

        .accordion-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 18px 8px;
            cursor: pointer;
            transition: background-color var(--transition-speed) ease;
        }

        .accordion-header:hover {
            background-color: rgba(217, 169, 195, 0.15);
        }


        .accordion-header h3 {
            margin: 0;
            font-size: 0.95rem;
            font-weight: 500;
            color: var(--secondary-text-color);
            transition: color var(--transition-speed) ease;
        }

        .accordion-item.active .accordion-header h3 {
            color: var(--primary-text-color);
            font-weight: 700;
        }

        .accordion-icon {
            font-weight: 400;
            font-size: 1.3rem;
            transition: transform var(--transition-speed) cubic-bezier(0.25, 0.8, 0.25, 1);
            color: var(--accent-color);
        }

        .accordion-item.active .accordion-icon {
            transform: rotate(45deg);
        }

        .accordion-content {
            max-height: 0;
            overflow: hidden;
            transition: max-height var(--transition-speed) ease-in-out;
            padding: 0 24px;
        }

        .accordion-content-inner {
            padding-bottom: 24px;
            color: var(--secondary-text-color);
            font-size: 0.9rem;
            /* 保留文本中的换行 */
            white-space: pre-wrap;
        }

    </style>
</head>
